import sys

def edit(p, pairs):
    s = open(p).read()
    for a, b in pairs:
        if s.count(a) != 1:
            sys.exit(f'{p}: {s.count(a)} of {a[:80]!r}')
        s = s.replace(a, b)
    open(p, 'w').write(s)

